#include "../adapter/NativeTransform.hpp"
#include <cassert>
int main(){using namespace ProFabX;NativeTransform instance=NativeTransform::Identity(),volume=NativeTransform::Identity(),delta=NativeTransform::Identity();instance.translate(Eigen::Vector3d(70,80,20));volume.translate(Eigen::Vector3d(-5,-10,-15));const auto baseline=instance*volume;delta.translate(Eigen::Vector3d(10,-20,5));delta.rotate(Eigen::AngleAxisd(.6,Eigen::Vector3d::UnitZ()));auto movedVolume=volume;movedVolume.rotate(Eigen::AngleAxisd(.4,Eigen::Vector3d::UnitX()));const auto nativeInstance=instanceForDelta(delta,baseline,movedVolume);assert((deltaFromNative(nativeInstance,movedVolume,baseline).matrix()-delta.matrix()).norm()<1e-9);assert((nativeInstance*movedVolume).matrix().isApprox((delta*baseline).matrix()));return 0;}
